const HEAVY_PATTERNS = [
  /^node:/,
  /^sharp$/,
  /^@aws-sdk\//,
  /^@prisma\/client$/,
  /^prisma$/,
  /^pg$/,
  /^mysql2(?:\/|$)/,
  /^puppeteer(?:-core)?(?:\/|$)/,
  /^playwright(?:-core)?(?:\/|$)/,
  /^bcrypt$/,
  /^jsonwebtoken$/,
  /^canvas$/,
  /^@google-cloud\//,
