  '<!-- To change gate thresholds, edit lib/gates/*.mjs metadata exports. -->\n\n';

async function main() {
  const expected = {
    'scanner-patterns.md': renderScanners(),
    'candidates.md': renderCandidates(),
  };

  let stale = false;
  for (const [name, content] of Object.entries(expected)) {
    let actual;
